 "content": "def transform(grid):
    """Repeat the diagonal-stripe sequence across rows and columns."""
    h, w = len(grid), len(grid[0])
    valid_orientations = []
    for orientation in ('diff', 'sum'):
        key_fn = (lambda r, c: c - r) if orientation == 'diff' else (lambda r, c: r + c)
        stripes = {}
        mixed = False
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    key = key_fn(r, c)
                    if key in stripes and stripes[key] != color:
                        mixed = True
                        break
                    stripes[key] = color
            if mixed:
                break
        if not mixed and stripes:
            period = len(stripes)
            phases = {}
            consistent = True
            for key, color in stripes.items():
                phase = key % period
                if phase in phases and phases[phase] != color:
                    consistent = False
                    break
                phases[phase] = color
            if consistent and len(phases) == period:
                valid_orientations.append((orientation, period, phases))
    if not valid_orientations:
        return [row[:] for row in grid]
    orientation, period, phases = valid_orientations[0]
    key_fn = (lambda r, c: c - r) if orientation == 'diff' else (lambda r, c: r + c)
    return [[phases[key_fn(r, c) % period] for c in range(w)] for r in range(h)]


def _make(h, w, orientation, clue_lines):
    grid = [[0] * w for _ in range(h)]
    for key, color in clue_lines:
        for r in range(h):
            for c in range(w):
                k = c - r if orientation == 'diff' else r + c
                if k == key:
                    grid[r][c] = color
    return grid


def _tile(h, w, orientation, cycle):
    return [[cycle[(c-r if orientation == 'diff' else r+c) % len(cycle)]
             for c in range(w)] for r in range(h)]


